use vstd::prelude::*;

verus! {

#[verifier(publish)]
struct Interval {
    pub min: i32,
    pub max: i32,
}

#[verifier(publish)]
struct ChebyshevPoly {
    pub coef: Vec<i32>,
    pub domain: Interval,
    pub window: Interval,
}

fn chebyshev(coef: Vec<i8>) -> (result: ChebyshevPoly)
    requires
        coef.len() > 0,
    ensures
        // The coefficients are converted one‐to‐one to i32
        result.coef.len() == coef.len(),
        forall |j: nat| j < coef.len() ==> result.coef[j] == (coef[j] as i32),
        // Domain is [-1,1] and valid
        result.domain.min == -1,
        result.domain.max == 1,
        result.domain.min < result.domain.max,
        // Window is [-1,1] and valid
        result.window.min == -1,
        result.window.max == 1,
        result.window.min < result.window.max,
{
    let len = coef.len();
    let mut new_coef: Vec<i32> = Vec::with_capacity(len);
    let mut i: usize = 0;
    while i < len
        invariant
            i <= len,
            new_coef.len() == i,
            // prefix of new_coef matches converted input
            forall |j: nat| j < i ==> new_coef[j] == (coef[j] as i32),
        decreases
            len - i,
    {
        new_coef.push(coef[i] as i32);
        i = i + 1;
    }

    let domain = Interval { min: -1, max: 1 };
    let window = Interval { min: -1, max: 1 };

    // show validity of the intervals
    assert(domain.min < domain.max);
    assert(window.min < window.max);

    ChebyshevPoly {
        coef: new_coef,
        domain,
        window,
    }
}

} // verus!

